import{_ as a,o as n,c as t,a2 as p}from"./chunks/framework.B-bxTAy7.js";const g=JSON.parse('{"title":"时钟树","description":"时钟源、PLL 倍频、总线分频链、外设时钟使能，以及定时器时钟自动乘二。","frontmatter":{"title":"时钟树","description":"时钟源、PLL 倍频、总线分频链、外设时钟使能，以及定时器时钟自动乘二。"},"headers":[],"relativePath":"prereq/clock-tree.md","filePath":"prereq/clock-tree.md","lastUpdated":null}'),e={name:"prereq/clock-tree.md"};function m(l,s,c,r,i,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="时钟树" tabindex="-1">时钟树 <a class="header-anchor" href="#时钟树" aria-label="Permalink to &quot;时钟树&quot;">​</a></h1><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ul><li><strong>时钟是 MCU 的心跳</strong>。每个外设都有独立的时钟开关，<strong>上电后外设时钟默认是关的</strong>（省电），必须先使能再用。</li><li>上电默认用<strong>内部 HSI</strong>（RC 振荡器，误差 1%~2%）。要达到标称主频，必须手工配置：外部晶振 HSE → PLL 倍频 → SYSCLK。</li><li><strong>时钟树是一条分频链</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>SYSCLK</mtext><mo>→</mo><mtext>HCLK(AHB)</mtext><mo>→</mo><mtext>PCLK1/PCLK2(APB)</mtext><mo>→</mo></mrow><annotation encoding="application/x-tex">\\text{SYSCLK}\\to\\text{HCLK(AHB)}\\to\\text{PCLK1/PCLK2(APB)}\\to</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">SYSCLK</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">HCLK(AHB)</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">PCLK1/PCLK2(APB)</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span></span></span></span> 各外设。每级分频系数都受芯片上限约束。</li><li><strong>APB 预分频系数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo mathvariant="normal">≠</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\ne1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 时，挂在该总线上的定时器时钟自动 ×2</strong>。忘了这条，延时与 PWM 频率整体差一倍。</li><li>忘了使能时钟的症状是：<strong>配置全对、寄存器也写了、外设毫无反应、且不报错</strong>。</li></ul><p><strong>为什么它承重</strong>：所有基于时间的计算——延时、波特率、PWM 频率、采样率——都以时钟为基准。时钟算错，程序照样编译、照样跑、照样「看起来在工作」，只是时间全错，最难查。</p><h2 id="典型数值" tabindex="-1">典型数值 <a class="header-anchor" href="#典型数值" aria-label="Permalink to &quot;典型数值&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时钟源</th><th>频率</th><th>精度</th><th>用途</th></tr></thead><tbody><tr><td><strong>HSI</strong></td><td>8 MHz（F1）/ 16 MHz（F4）</td><td>差（±1%~2%，温漂）</td><td>上电默认；HSE 失效时的备份</td></tr><tr><td><strong>HSE</strong></td><td>通常 4~25 MHz</td><td>高（几十 ppm）</td><td><strong>主时钟源</strong></td></tr><tr><td><strong>LSI</strong></td><td>约 40 kHz</td><td>很差</td><td>独立看门狗 IWDG</td></tr><tr><td><strong>LSE</strong></td><td>32.768 kHz</td><td>高</td><td>RTC 实时时钟</td></tr></tbody></table><p>F103 经典配置（HSE 8 MHz、PLL ×9）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>SYSCLK</mtext><mo>=</mo><mn>8</mn><mo>×</mo><mn>9</mn><mo>=</mo><mn>72</mn><mtext> </mtext><mtext>MHz</mtext><mo separator="true">,</mo><mspace width="1em"></mspace><mtext>HCLK</mtext><mo>=</mo><mn>72</mn><mtext> </mtext><mtext>MHz</mtext><mo separator="true">,</mo><mspace width="1em"></mspace><mtext>PCLK1</mtext><mo>=</mo><mn>36</mn><mtext> </mtext><mtext>MHz</mtext><mo separator="true">,</mo><mspace width="1em"></mspace><mtext>PCLK2</mtext><mo>=</mo><mn>72</mn><mtext> </mtext><mtext>MHz</mtext></mrow><annotation encoding="application/x-tex">\\text{SYSCLK}=8\\times9=72\\,\\text{MHz},\\quad \\text{HCLK}=72\\,\\text{MHz},\\quad \\text{PCLK1}=36\\,\\text{MHz},\\quad \\text{PCLK2}=72\\,\\text{MHz} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">SYSCLK</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">9</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">HCLK</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">PCLK1</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">36</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">PCLK2</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span></span></span></span></span><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>TIM2–7 时钟</mtext><mo>=</mo><mn>36</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>72</mn><mtext> </mtext><mtext>MHz</mtext><mspace width="1em"></mspace><mtext>（</mtext><mi>A</mi><mi>P</mi><mi>B</mi><mn>1</mn><mtext>预分频为</mtext><mn>2</mn><mtext>，</mtext><mo>×</mo><mn>2</mn><mtext>）</mtext></mrow><annotation encoding="application/x-tex">\\text{TIM2\\text{--}7 时钟}=36\\times2=72\\,\\text{MHz}\\quad（APB1 预分频为 2，\\times2） </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">TIM2</span><span class="mord text"><span class="mord">–</span></span><span class="mord">7 </span><span class="mord cjk_fallback">时钟</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">36</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span><span class="mspace" style="margin-right:1em;"></span><span class="mord cjk_fallback">（</span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord">1</span><span class="mord cjk_fallback">预分频为</span><span class="mord">2</span><span class="mord cjk_fallback">，</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">2</span><span class="mord cjk_fallback">）</span></span></span></span></span><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>TIM1 时钟</mtext><mo>=</mo><mn>72</mn><mtext> </mtext><mtext>MHz</mtext><mspace width="1em"></mspace><mtext>（</mtext><mi>A</mi><mi>P</mi><mi>B</mi><mn>2</mn><mtext>预分频为</mtext><mn>1</mn><mtext>，不</mtext><mo>×</mo><mn>2</mn><mtext>）</mtext></mrow><annotation encoding="application/x-tex">\\text{TIM1 时钟}=72\\,\\text{MHz}\\quad（APB2 预分频为 1，不 \\times2） </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">TIM1 </span><span class="mord cjk_fallback">时钟</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span><span class="mspace" style="margin-right:1em;"></span><span class="mord cjk_fallback">（</span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord">2</span><span class="mord cjk_fallback">预分频为</span><span class="mord">1</span><span class="mord cjk_fallback">，不</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">2</span><span class="mord cjk_fallback">）</span></span></span></span></span><ul><li><strong>APB1 上限 36 MHz</strong>（F103），所以必须至少二分频。</li><li>不配时钟时 F103 跑 8 MHz，所有时间计算<strong>差 9 倍</strong>——这是「程序能跑但串口全乱码」的经典原因。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>忘了使能外设时钟</strong>：<code>RCC-&gt;APB2ENR |= (1 &lt;&lt; 2)</code> 或 <code>__HAL_RCC_GPIOA_CLK_ENABLE()</code>。</li><li><strong>算定时器时钟用了 PCLK 而不是 ×2 后的值</strong>。</li><li>算 UART 波特率时用了 ×2 后的时钟——<strong>USART 不享受 ×2</strong>，只有定时器享受。</li><li>PLL 倍频后不检查上限：SYSCLK 超过芯片最大值，芯片直接进不了正常状态（表现为「卡在时钟配置之后」）。</li><li>上拉引脚与外设时钟混为一谈：GPIO 配成开漏后仍需时钟，只是需求少一个而已。</li></ul><div class="tip custom-block" id="ex-clock-tree-1"><p class="custom-block-title">例 1 · 为什么定时器算出来快了一倍</p><p>某 F103 工程：HSE 8 MHz、PLL ×9、AHB ÷1、APB1 ÷2。写代码时按 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mo>=</mo><mstyle scriptlevel="0" displaystyle="true"><mfrac><mrow><mtext>ARR</mtext><mo>+</mo><mn>1</mn></mrow><mtext>PCLK1</mtext></mfrac></mstyle></mrow><annotation encoding="application/x-tex">T=\\dfrac{\\text{ARR}+1}{\\text{PCLK1}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">PCLK1</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">ARR</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span> 计算定时周期，PCLK1 = 36 MHz。但实测周期只有设计值的一半。</p><p><strong>原因</strong>：APB1 的预分频系数是 2（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo mathvariant="normal">≠</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\ne1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>），此时挂在 APB1 上的定时器时钟 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>36</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>72</mn><mtext> </mtext><mtext>MHz</mtext></mrow><annotation encoding="application/x-tex">=36\\times2=72\\,\\text{MHz}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">36</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span></span></span></span>，而不是 36 MHz。</p><p><strong>修正</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mo>=</mo><mstyle scriptlevel="0" displaystyle="true"><mfrac><mrow><mtext>ARR</mtext><mo>+</mo><mn>1</mn></mrow><mrow><mn>72</mn><mtext> </mtext><mtext>MHz</mtext></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">T=\\dfrac{\\text{ARR}+1}{72\\,\\text{MHz}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">72</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">MHz</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">ARR</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>，即同样的 ARR 得到两倍的频率。</p><p><strong>同时注意</strong>：同一个 APB1 上的 USART2 用的仍是 <strong>PCLK1 = 36 MHz</strong>，不乘二——<strong>定时器与串口在同一条总线上却用不同的时钟</strong>，这是最容易算混的一处。</p><blockquote><p><strong>为什么这么想</strong> ×2 的设计意图是：即使你为了省电把 APB1 降到 36 MHz，定时器仍能拿到 72 MHz 的计数分辨率，不至于牺牲定时精度。所以这条规则是「总线的频率」与「外设实际吃到的频率」故意脱钩的结果。</p></blockquote></div><blockquote><p>深入：完整内容见 <a href="./../embedded/clock">04 · 时钟系统（RCC 与时钟树）</a></p></blockquote>',15)])])}const d=a(e,[["render",m]]);export{g as __pageData,d as default};
